<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\Customer; use App\Models\CustomerContact; use App\Services\AuthorizationService; use App\Support\TenantContext; use Illuminate\Http\Request;
final class CustomerController { public function index(Request $r){$q=Customer::where('tenant_id',app(TenantContext::class)->id())->with('contacts')->when($r->filled('search'),fn($q)=>$q->where('name','ilike','%'.$r->string('search').'%'))->orderBy('name');return response()->json(['data'=>$q->paginate(min($r->integer('per_page',25),100))]);} public function store(Request $r,AuthorizationService $a){$t=app(TenantContext::class)->id();abort_unless($a->allows($r->user(),$t,'sales.manage'),403);$d=$r->validate(['name'=>'required|string|max:200','code'=>'required|alpha_dash|max:50','email'=>'nullable|email','phone'=>'nullable|string|max:50','billing_address'=>'nullable|string','shipping_address'=>'nullable|string','tax_identifier'=>'nullable|string|max:100']);return response()->json(['data'=>Customer::create([...$d,'tenant_id'=>$t])],201);} public function contact(Request $r,Customer $customer,AuthorizationService $a){$t=app(TenantContext::class)->id();abort_unless($customer->tenant_id===$t,404);abort_unless($a->allows($r->user(),$t,'sales.manage'),403);$d=$r->validate(['name'=>'required|string|max:200','email'=>'nullable|email','phone'=>'nullable|string|max:50','role'=>'nullable|string|max:100']);return response()->json(['data'=>CustomerContact::create([...$d,'tenant_id'=>$t,'customer_id'=>$customer->id])],201);} }
